```cypher
MATCH (sku:SKU {is_bundle: false})-[:EXPLODES]->(part:Component {component_id: 'CAB-903-WAL-02318', is_assembly: false})
WHERE EXISTS {
    MATCH (sku)-[:EXPLODES]->(part)
    WHERE part.valid_from <= date('2026-10-01')
      AND (part.valid_to IS NULL OR date('2026-10-01') <= part.valid_to)
}
RETURN COUNT(DISTINCT sku.sku_id) AS count;
```

